// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 t, address actor) public {
        vm.assume(t > 0);
        vm.assume(actor != address(0));
        vm.warp(t);

        // first call at timestamp t succeeds in both P and M
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // GENERAL RULE: any second call at the SAME timestamp must revert
        // (P requires strictly increasing timestamps); M accepts it.
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertTrue(!ok2, "second same-timestamp call must revert");
    }
}
